css:
[data-bz-section="location-cta"] .bz-block { padding-block: 0 }
/* This handoff keeps its grey and dark bands to the same 1280px well as its white ones. */
.bz-sharedsection[data-bz-section="location-cta"] > .bz-section > .bz-container { max-width: var(--container) }
[data-bz-section="location-cta"] .bz-block + .bz-block { padding-block-start: 0 }
/* Handoff .section--dark: the ink band, centred. The call button dials this branch. */
[data-bz-section="location-cta"] > .bz-section { padding-block: 90px; text-align: center }
[data-bz-section="location-cta"] .bz-eyebrow { color: var(--chrome-meta); text-align: center; margin: 0 0 18px }
[data-bz-section="location-cta"] h2 { font-size: 34px; line-height: 1.7; font-weight: 800; margin: 0 0 18px; color: #fff; text-align: center }
[data-bz-section="location-cta"] [data-bz-node^="lc-body"] .bz-text { margin-inline: auto; max-width: 620px }
[data-bz-section="location-cta"] [data-bz-node^="lc-body"] p { color: var(--chrome-body); font-size: 15px; line-height: 1.7; margin: 0 auto 30px }
[data-bz-section="location-cta"] .bz-btns { justify-content: center; margin-block: 0; gap: 14px }
[data-bz-section="location-cta"] .bz-btn { min-height: 48px; padding: 0 26px; border-radius: 0; font: 700 14px / 1.2 var(--font-body); letter-spacing: 0; text-transform: none }
[data-bz-section="location-cta"] .bz-btn--primary { background: var(--accent-dark); color: #fff; border: 1px solid transparent }
[data-bz-section="location-cta"] .bz-btn--primary:hover { background: var(--accent-dark); filter: brightness(.9) }
[data-bz-section="location-cta"] .bz-btn--secondary { background: transparent; color: #fff; border: 1px solid #fff }
[data-bz-section="location-cta"] .bz-btn--secondary:hover { background: #fff; color: var(--chrome) }
@media (max-width: 640px) { [data-bz-section="location-cta"] > .bz-section { padding-block: 64px } [data-bz-section="location-cta"] h2 { font-size: 26px } }
